arguments.command:
cat > /tmp/friends-conv/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) echo "x-access-token" ;;
  *) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/friends-conv/askpass.sh
cd /tmp/friends-conv/monica && GIT_ASKPASS=/tmp/friends-conv/askpass.sh git push origin HEAD:refs/heads/friend/monica 2>&1 | tail -3
